using UnityEngine;
using UnityEditor;
using System.Linq;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var allObjs = GameObject.FindObjectsByType<GameObject>(FindObjectsSortMode.None);
        result.Log("Total GameObjects in scene: {0}", allObjs.Length);

        var trumpAtk = GameObject.Find("trump_atk") ?? allObjs.FirstOrDefault(g => g.name.ToLower().Contains("trump_atk"));
        var trumpVichim = GameObject.Find("trump_vichim") ?? allObjs.FirstOrDefault(g => g.name.ToLower().Contains("trump_vichim") || g.name.ToLower().Contains("trump_victim") || g.name.ToLower().Contains("vichim"));

        result.Log("trump_atk found: {0}", trumpAtk != null ? trumpAtk.name : "null");
        result.Log("trump_vichim found: {0}", trumpVichim != null ? trumpVichim.name : "null");

        if (trumpAtk != null)
        {
            LogHierarchy(trumpAtk, "", result);
        }
        if (trumpVichim != null)
        {
            LogHierarchy(trumpVichim, "", result);
        }
    }

    void LogHierarchy(GameObject obj, string indent, ExecutionResult result)
    {
        result.Log("{0}{1} (Pos: {2}, Rot: {3}, Scale: {4})", indent, obj.name, obj.transform.position, obj.transform.eulerAngles, obj.transform.localScale);
        foreach (Transform child in obj.transform)
        {
            LogHierarchy(child.gameObject, indent + "  ", result);
        }
    }
}

