using UnityEngine;
using UnityEditor;
using UnityEngine.UI;
using TMPro;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trumpAtk = GameObject.Find("Trump_Atk");
        var trumpVic = GameObject.Find("Trump_Victim");

        if (trumpAtk == null || trumpVic == null)
        {
            result.LogError("Could not find Trump_Atk or Trump_Victim");
            return;
        }

        var headAtk = trumpAtk.transform.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_NeckTwist01/CC_Base_NeckTwist02/CC_Base_Head");
        var headVic = trumpVic.transform.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_NeckTwist01/CC_Base_NeckTwist02/CC_Base_Head");

        if (headAtk == null || headVic == null)
        {
            result.LogError("Could not find CC_Base_Head on one or both characters");
            return;
        }

        var fontAsset = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/TextMesh Pro/Resources/Fonts & Materials/LiberationSans SDF.asset");
        var uiSprite = AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/UISprite.psd");

        // Create bubble for Trump_Atk
        var bubbleAtk = CreateSpeechBubble(headAtk, "SpeechBubble_TrumpAtk", "Sẵn sàng chiến đấu!", fontAsset, uiSprite, result, new Color(0.98f, 0.98f, 1f, 0.95f), new Color(0.12f, 0.12f, 0.15f, 1f));

        // Create bubble for Trump_Victim
        var bubbleVic = CreateSpeechBubble(headVic, "SpeechBubble_TrumpVictim", "Không dễ nuốt đâu!", fontAsset, uiSprite, result, new Color(1f, 0.98f, 0.95f, 0.95f), new Color(0.15f, 0.12f, 0.12f, 1f));

        EditorUtility.SetDirty(trumpAtk);
        EditorUtility.SetDirty(trumpVic);
        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(trumpAtk.scene);

        result.Log("Successfully created World Space speech bubbles for Trump_Atk and Trump_Victim!");
    }

    GameObject CreateSpeechBubble(Transform parentHead, string bubbleName, string message, TMP_FontAsset font, Sprite sprite, ExecutionResult result, Color bgColor, Color textColor)
    {
        // Remove existing if any
        var existing = parentHead.Find(bubbleName);
        if (existing != null)
        {
            result.DestroyObject(existing.gameObject);
        }

        // 1. Canvas GameObject
        var canvasObj = new GameObject(bubbleName);
        canvasObj.transform.SetParent(parentHead, false);

        var canvas = canvasObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        canvas.worldCamera = Camera.main;

        var scaler = canvasObj.AddComponent<CanvasScaler>();
        scaler.dynamicPixelsPerUnit = 4f;

        canvasObj.AddComponent<GraphicRaycaster>();

        var rectTransform = canvasObj.GetComponent<RectTransform>();
        rectTransform.sizeDelta = new Vector2(240f, 95f);
        rectTransform.localScale = new Vector3(0.005f, 0.005f, 0.005f);

        // Position directly above head
        rectTransform.localPosition = new Vector3(0f, 0.42f, 0f);

        // Face camera initially (world rotation looking forward towards camera)
        rectTransform.rotation = Quaternion.Euler(0f, 0f, 0f);

        result.RegisterObjectCreation(canvasObj);

        // 2. Background Box
        var bgObj = new GameObject("Bubble_Background");
        bgObj.transform.SetParent(canvasObj.transform, false);

        var bgImage = bgObj.AddComponent<Image>();
        bgImage.sprite = sprite;
        bgImage.type = Image.Type.Sliced;
        bgImage.color = bgColor;
        bgImage.raycastTarget = false;

        var bgRect = bgObj.GetComponent<RectTransform>();
        bgRect.anchorMin = new Vector2(0f, 0.12f);
        bgRect.anchorMax = new Vector2(1f, 1f);
        bgRect.offsetMin = Vector2.zero;
        bgRect.offsetMax = Vector2.zero;

        result.RegisterObjectCreation(bgObj);

        // 3. Tail (pointing down towards character)
        var tailObj = new GameObject("Bubble_Tail");
        tailObj.transform.SetParent(canvasObj.transform, false);

        var tailImage = tailObj.AddComponent<Image>();
        tailImage.sprite = sprite;
        tailImage.color = bgColor;
        tailImage.raycastTarget = false;

        var tailRect = tailObj.GetComponent<RectTransform>();
        tailRect.anchorMin = new Vector2(0.5f, 0f);
        tailRect.anchorMax = new Vector2(0.5f, 0f);
        tailRect.pivot = new Vector2(0.5f, 1f);
